import Foundation

/// Converts supported web links into routes understood by the app coordinators.
///
/// The API currently shares offers using links such as
/// `https://upgrade.loh.com.sa/shareCoupon/{coupon_id}`. The parser also accepts
/// the equivalent coupon/offer path and query formats so links generated by an
/// older web client continue to open the same offer detail screen. Merchant
/// links use the corresponding store/merchant/provider path and query formats.
enum AppDeepLink {
    private static let supportedHosts: Set<String> = [
        "upgrade.loh.com.sa",
        "www.upgrade.loh.com.sa",
        "loh.com.sa",
        "www.loh.com.sa"
    ]

    private static let offerPathMarkers: Set<String> = [
        "coupon", "coupons", "offer", "offers",
        "sharecoupon", "share-coupon", "shareoffer", "share-offer"
    ]

    private static let merchantPathMarkers: Set<String> = [
        "store", "stores", "merchant", "merchants", "provider", "providers",
        "sharestore", "share-store", "sharemerchant", "share-merchant",
        "shareprovider", "share-provider"
    ]

    static func route(for url: URL) -> HomeRoute? {
        guard ["http", "https"].contains(url.scheme?.lowercased() ?? ""),
              let host = url.host?.lowercased(), supportedHosts.contains(host) else {
            return nil
        }

        let pathComponents = url.path
            .split(separator: "/")
            .compactMap { $0.removingPercentEncoding }

        if let markerIndex = pathComponents.firstIndex(where: {
            offerPathMarkers.contains($0.lowercased())
        }), markerIndex + 1 < pathComponents.count,
           let id = positiveID(pathComponents[markerIndex + 1]) {
            return .offerID(id)
        }

        if let markerIndex = pathComponents.firstIndex(where: {
            merchantPathMarkers.contains($0.lowercased())
        }), markerIndex + 1 < pathComponents.count,
           let id = positiveInt(pathComponents[markerIndex + 1]) {
            return .merchantID(id)
        }

        let queryItems = URLComponents(url: url, resolvingAgainstBaseURL: false)?.queryItems ?? []
        for key in ["coupon_id", "couponId", "offer_id", "offerId"] {
            if let value = queryItems.first(where: { $0.name == key })?.value,
                   let id = positiveID(value) {
                return .offerID(id)
            }
        }

        for key in ["store_id", "storeId", "merchant_id", "merchantId", "provider_id", "providerId"] {
            if let value = queryItems.first(where: { $0.name == key })?.value,
               let id = positiveInt(value) {
                return .merchantID(id)
            }
        }

        if let value = queryItems.first(where: { $0.name == "id" })?.value,
           let id = positiveInt(value) {
            let type = queryItems.first(where: { ["type", "entity", "resource"].contains($0.name) })?.value?
                .lowercased() ?? ""
            if ["store", "merchant", "provider"].contains(type) {
                return .merchantID(id)
            }
            return .offerID(String(id))
        }

        return nil
    }

    private static func positiveID(_ value: String) -> String? {
        positiveInt(value).map(String.init)
    }

    private static func positiveInt(_ value: String) -> Int? {
        guard let id = Int(value), id > 0 else { return nil }
        return id
    }
}
